An example (contd.)
We can randomly assign individuals in this population to taking ibuprofen or not, and then see what happens.


Code
set.seed(1038)
data_observed &lt;- dat |&gt; 
  mutate(
    exposure = ifelse(rbinom(n(),1, 0.5) == 1, 'ibf','no_ibf'),
    observed_outcome = ifelse(exposure=='ibf', headache_ibf, headache_noibf)
  ) |&gt; 
  select(id, exposure, observed_outcome)
output &lt;- data_observed |&gt; 
  group_by(exposure) |&gt; 
  summarise(avg_outcome = mean(observed_outcome)) |&gt; 
  pivot_wider(names_from = exposure, values_from = avg_outcome) |&gt; 
  mutate(causal_effect = ibf - no_ibf)
output


# A tibble: 1 × 3
    ibf no_ibf causal_effect
  &lt;dbl&gt;  &lt;dbl&gt;         &lt;dbl&gt;
1  2.57   5.67         -3.10


From this randomized experiment, we see that the estimated causal effect is -3.1 hours, which is close to the true average causal effect of -3.2 hours.


Code
library(infer)
library(geomtextpath)
set.seed(384)
boot_dist = data_observed |&gt; 
  specify(observed_outcome ~ exposure) |&gt; 
  generate(reps = 1000, type='bootstrap') |&gt; 
  calculate(stat = 'diff in means', order = c('ibf','no_ibf'))
visualize(boot_dist) + shade_confidence_interval(endpoints = get_ci(boot_dist)) +
  geom_textvline(xintercept = -3.2, color = 'red', label = 'true effect') +  labs(x = "Difference in means") + theme_minimal() + theme(axis.text.y = element_blank(), axis.title.y = element_blank())

Propensity Score Matching
Match treated units to control units with similar propensity scores:


Code
library(MatchIt)
library(glue)

# 1:1 nearest-neighbor matching on propensity score
m_out &lt;- matchit(A ~ X1 + X2, data = df, method = 'nearest', ratio = 1)

# Extract matched sample
matched &lt;- match.data(m_out)

# Estimate ATE on matched sample
matched_ate &lt;- matched |&gt;
  group_by(A) |&gt;
  summarize(mean_Y = mean(Y), .groups = 'drop') |&gt;
  summarize(matched_ATE = diff(mean_Y))

matched |&gt; mutate(A = factor(A)) |&gt; 
  specify(Y ~ A) |&gt; 
  generate(1000, type='bootstrap') |&gt; 
  calculate(stat = 'diff in means', order = c('1','0')) |&gt; 
  get_ci() |&gt; 
  glue_data("Estimated ATE (Matching): {round(matched_ate$matched_ATE,2)} (95% CI: [{round(lower_ci,2)}, {round(upper_ci,2)}])")


Estimated ATE (Matching): 1.45 (95% CI: [1.34, 1.58])


Matching directly tries to create a balanced sample where treated and control are comparable. It depends on how well matches can be found, and, as we can see, might not fully remove bias if the propensity model is misspecified or we have poor matching within our data.

Simulating the SC population

set.seed(1234)
sc_pop &lt;- usdata::pop_age_2019 |&gt;
  filter(state == "SC", age &gt;= 20, age &lt;= 35) |&gt;
  pull(population) |&gt;
  sum()
behavior_now &lt;- tibble(homeowner = rbinom(sc_pop, 1, 0.15)) |&gt;
  mutate(leaves = ifelse(homeowner == 1, rbinom(n(), 1, 0.01), rbinom(n(), 1, 0.15))) |&gt;
  mutate(cost = leaves * 50000)

intervention &lt;- tibble(homeowner = rbinom(sc_pop, 1, 0.15)) |&gt;
  mutate(takes_program = ifelse(homeowner == 1, 0, rbinom(n(), 1, 0.3))) |&gt;
  mutate(leave_prob = case_when(
    homeowner == 1 ~ 0.01,
    takes_program == 1 ~ 0.10,
    TRUE ~ 0.15
  )) |&gt;
  mutate(leaves = rbinom(n(), 1, leave_prob)) |&gt;
  mutate(cost = leaves * 50000 + takes_program * 1000)

total_cost_now &lt;- sum(behavior_now$cost)
total_cost_intervention &lt;- sum(intervention$cost)

This is one simulation of the total cost now and with the intervention. To understand the variability, we need to repeat this many times.

Running many simulations
First, encapsulate the logic in a function:

N &lt;- usdata::pop_age_2019 |&gt;
  filter(state == "SC", age &gt;= 20, age &lt;= 35) |&gt;
  pull(population) |&gt;
  sum()

sim_function &lt;- function(N) {
  behavior_now &lt;- tibble(homeowner = rbinom(N, 1, 0.15)) |&gt;
    mutate(leaves = ifelse(homeowner == 1, rbinom(n(), 1, 0.01), rbinom(n(), 1, 0.15))) |&gt;
    mutate(cost = leaves * 50000)

  intervention &lt;- tibble(homeowner = rbinom(N, 1, 0.15)) |&gt;
    mutate(takes_program = ifelse(homeowner == 1, 0, rbinom(n(), 1, 0.3))) |&gt;
    mutate(leave_prob = case_when(
      homeowner == 1 ~ 0.01,
      takes_program == 1 ~ 0.10,
      TRUE ~ 0.15
    )) |&gt;
    mutate(leaves = rbinom(n(), 1, leave_prob)) |&gt;
    mutate(cost = leaves * 50000 + takes_program * 1000)

  total_cost_now &lt;- sum(behavior_now$cost)
  total_cost_intervention &lt;- sum(intervention$cost)
  return(data.frame("now" = total_cost_now, "intervention" = total_cost_intervention))
}

Running a permutation test
To perform a permutation test, we’d do, say, 1000 random shuffles, and then compute the difference in the group means based on the shuffled labels each time.

n_permutation &lt;- 1000
set.seed(2894)
difference_perms &lt;- replicate(n_permutation, {
  shuffled_labels &lt;- sample(emissions_data$filter)
  mean_A &lt;- mean(emissions_data$reduction[shuffled_labels == "A"])
  mean_B &lt;- mean(emissions_data$reduction[shuffled_labels == "B"])
  return(mean_B - mean_A)
})

But how would we do this using simulation?

set.seed(1234)
n_sims &lt;- 1000
sample_size &lt;- 50 # initial guess
power_simulation &lt;- function(sample_size, n_sims, mu0, mu1, sd) {
  rejections &lt;- replicate(n_sims, {
    sample_data &lt;- rnorm(sample_size, mean = mu1, sd = sd)
    p_value &lt;- t.test(sample_data, mu = mu0, alternative = "greater")$p.value
    return(p_value &lt; 0.05)
  })
  power &lt;- mean(rejections)
  return(power)
}
desired_power &lt;- 0.8
current_power &lt;- 0
while (current_power &lt; desired_power) {
  current_power &lt;- power_simulation(
    sample_size,
    n_sims,
    mu0 = 35,
    mu1 = 41,
    sd = sd(dc_pop$age)
  )
  if (current_power &lt; desired_power) {
    sample_size &lt;- sample_size + 5 # increment sample size
  }
}
sample_size

[1] 75


We would need a sample size of approximately 75 to achieve this power using simulation.
See this interactive widget for exploring how different parameters affect power and sample size.

Brackets
{} are used to contain groups of commands/statements


A conditional statement


Code
if (age &lt; 18){
   person &lt;- 'Minor'
} else if (age &gt; 65) {
  person &lt;- 'Senior'
} else {
  person &lt;- 'Adult'
}



A function definition


Code
my_mean &lt;- function(x, na.rm = T){
  if(na.rm){
    x &lt;- x[!is.na(x)]
  }
  s &lt;- sum(x)
  n &lt;- length(x)
  mn &lt;- s / n # There is a built-in function mean, so I don't use that word
  return(mn)
}

Defining functions
The basic syntax of a function is
&lt;function name&gt; &lt;- function(&lt;input argument(s)&gt;){
  &lt;code for instructions&gt;
  ...
  &lt;more code&gt;
  return(&lt;output object&gt;)
}

for-loops
Example:


Code
for(n in names(iris)){
  if(is.numeric(iris[,n])){
    print(glue::glue('The mean of {n} is {mean(iris[,n])}')) #&lt;&lt;
  }
}


The mean of Sepal.Length is 5.84333333333333
The mean of Sepal.Width is 3.05733333333333
The mean of Petal.Length is 3.758
The mean of Petal.Width is 1.19933333333333


You don’t need the &lt;list&gt; in the for-loop definition to be integers. In this case it is a list of strings.
Note that vectors are also considered lists for this purpose.















